syntax:
template <typename T>
void forward_function(T&& param) {
  // Using std::forward to perfectly forward param
  some_other_function(std::forward<T>(param));
}

//Example with lvalue
int x = 10;
forward_function(x); // x is passed as lvalue reference

//Example with rvalue
forward_function(10); // 10 is passed as rvalue reference
